    async def _extract_structural_causal_features(self, geological_model: Any) -> Dict[str, Any]:
        """Extract causal features from structural geological elements."""
        structural_features = []
        
        try:
            # Process structural features
            for feature in geological_model.structural_features:
                causal_attributes = {
                    'feature_id': feature.feature_id,
                    'feature_type': feature.feature_type,
                    'spatial_geometry': {
                        'strike': feature.strike,
                        'dip': feature.dip,
                        'dip_direction': feature.dip_direction,
                        'normal_vector': feature.normal_vector.tolist() if feature.normal_vector is not None else None,
                        'plane_equation': feature.plane_equation.tolist() if feature.plane_equation is not None else None
                    },
                    'causal_potential': {
                        'structural_control': self._assess_structural_control_potential(feature),
                        'fluid_flow_influence': self._assess_fluid_flow_influence(feature),
                        'stress_concentration': self._assess_stress_concentration(feature),
                        'deformation_pathway': self._assess_deformation_pathway_potential(feature)
                    },
                    'causal_connectivity': {
                        'network_position': self._calculate_structural_network_position(feature, geological_model),
                        'intersection_relationships': self._identify_intersection_relationships(feature, geological_model),
                        'kinematic_compatibility': self._assess_kinematic_compatibility(feature, geological_model)
                    }
                }
                structural_features.append(causal_attributes)
            
            # Discover causal relationships between structural features
            structural_causality_matrix = await self._discover_structural_causality(structural_features)
            
            return {
                'structural_causal_features': structural_features,
                'structural_causality_matrix': structural_causality_matrix,
                'structural_causal_network': self._build_structural_causal_network(structural_features, structural_causality_matrix),
                'feature_importance_ranking': self._rank_structural_feature_importance(structural_features)
            }
            
        except Exception as e:
            self.logger.error(f"Error extracting structural causal features: {e}")
            return {'error': str(e)}
    
    def _assess_structural_control_potential(self, feature: Any) -> float:
        """Assess the potential for structural control of geological processes."""
        try:
            control_score = 0.0
            
            # Feature type influence
            type_weights = {
                'fault': 0.9,
                'fracture': 0.7,
                'vein': 0.6,
                'contact': 0.8,
                'fold': 0.5
            }
            control_score += type_weights.get(feature.feature_type.lower(), 0.3)
            
            # Orientation significance
            if feature.dip is not None:
                # High-angle features typically have stronger control
                dip_influence = min(abs(feature.dip) / 90.0, 1.0)
                control_score += 0.3 * dip_influence
            
            # Confidence weighting
            if feature.confidence is not None:
                control_score *= feature.confidence
                
            return min(control_score, 1.0)
            
        except Exception:
            return 0.5  # Default moderate influence
    
    def _assess_fluid_flow_influence(self, feature: Any) -> float:
        """Assess the influence on fluid flow patterns."""
        try:
            flow_influence = 0.0
            
            # Feature type influences on fluid flow
            if feature.feature_type.lower() in ['fault', 'fracture', 'vein']:
                flow_influence += 0.8
            elif feature.feature_type.lower() == 'contact':
                flow_influence += 0.6
            else:
                flow_influence += 0.3
            
            # Orientation effects on flow
            if feature.dip is not None:
                # Moderate dip angles often provide optimal flow paths
                optimal_dip = 45.0
                dip_factor = 1.0 - abs(feature.dip - optimal_dip) / 90.0
                flow_influence += 0.2 * dip_factor
            
            return min(flow_influence, 1.0)
            
        except Exception:
            return 0.4  # Default moderate influence
    
    def _assess_stress_concentration(self, feature: Any) -> float:
        """Assess stress concentration potential."""
        try:
            stress_score = 0.0
            
            # Feature types that concentrate stress
            if feature.feature_type.lower() in ['fault', 'fracture']:
                stress_score += 0.7
            elif feature.feature_type.lower() == 'fold':
                stress_score += 0.6
            else:
                stress_score += 0.3
            
            # Sharp features concentrate more stress
            if hasattr(feature, 'curvature') and feature.curvature is not None:
                stress_score += 0.3 * min(feature.curvature, 1.0)
            else:
                stress_score += 0.2  # Assume moderate sharpness
            
            return min(stress_score, 1.0)
            
        except Exception:
            return 0.3
    
    def _assess_deformation_pathway_potential(self, feature: Any) -> float:
        """Assess potential as a deformation pathway."""
        try:
            pathway_score = 0.0
            
            # Feature type suitability as deformation pathway
            pathway_weights = {
                'fault': 0.9,
                'fracture': 0.8,
                'fold': 0.7,
                'contact': 0.5,
                'vein': 0.6
            }
            pathway_score += pathway_weights.get(feature.feature_type.lower(), 0.4)
            
            # Continuity assessment (based on confidence)
            if feature.confidence is not None:
                pathway_score *= feature.confidence
            
            return min(pathway_score, 1.0)
            
        except Exception:
            return 0.4
    
    def _calculate_structural_network_position(self, feature: Any, geological_model: Any) -> Dict[str, float]:
        """Calculate the network position of a structural feature."""
        try:
            # Create simplified network analysis
            centrality_metrics = {
                'degree_centrality': 0.0,
                'betweenness_centrality': 0.0,
                'closeness_centrality': 0.0,
                'eigenvector_centrality': 0.0
            }
            
            # Calculate connections to other features
            connections = 0
            for other_feature in geological_model.structural_features:
                if other_feature.feature_id != feature.feature_id:
                    # Simple distance-based connection assessment
                    if self._features_are_connected(feature, other_feature):
                        connections += 1
            
            # Normalize by total possible connections
            total_features = len(geological_model.structural_features) - 1
            if total_features > 0:
                centrality_metrics['degree_centrality'] = connections / total_features
            
            # Simplified centrality calculations
            centrality_metrics['betweenness_centrality'] = min(connections * 0.1, 1.0)
            centrality_metrics['closeness_centrality'] = centrality_metrics['degree_centrality']
            centrality_metrics['eigenvector_centrality'] = centrality_metrics['degree_centrality'] * 0.8
            
            return centrality_metrics
            
        except Exception:
            return {'degree_centrality': 0.0, 'betweenness_centrality': 0.0, 
                   'closeness_centrality': 0.0, 'eigenvector_centrality': 0.0}
    
    def _features_are_connected(self, feature1: Any, feature2: Any) -> bool:
        """Simple assessment of feature connectivity."""
        try:
            # Check if features intersect based on proximity
            if (hasattr(feature1, 'points') and hasattr(feature2, 'points') and
                feature1.points is not None and feature2.points is not None):
                
                # Calculate minimum distance between feature points
                min_distance = float('inf')
                for p1 in feature1.points:
                    for p2 in feature2.points:
                        distance = np.linalg.norm(p1 - p2)
                        min_distance = min(min_distance, distance)
                
                # Consider connected if within 100 meters
                return min_distance < 100.0
            
            return False
            
        except Exception:
            return False
    
    def _identify_intersection_relationships(self, feature: Any, geological_model: Any) -> List[Dict[str, Any]]:
        """Identify intersection relationships with other features."""
        intersections = []
        
        try:
            for other_feature in geological_model.structural_features:
                if other_feature.feature_id != feature.feature_id:
                    intersection_type = self._classify_intersection_type(feature, other_feature)
                    if intersection_type != 'none':
                        intersections.append({
                            'intersecting_feature_id': other_feature.feature_id,
                            'intersection_type': intersection_type,
                            'intersection_confidence': self._calculate_intersection_confidence(feature, other_feature)
                        })
            
            return intersections
            
        except Exception:
            return []
    
    def _classify_intersection_type(self, feature1: Any, feature2: Any) -> str:
        """Classify the type of intersection between two features."""
        try:
            if self._features_are_connected(feature1, feature2):
                # Simple classification based on feature types
                if feature1.feature_type == feature2.feature_type:
                    return 'parallel_intersection'
                elif 'fault' in [feature1.feature_type, feature2.feature_type]:
                    return 'fault_intersection'
                else:
                    return 'cross_cutting'
            return 'none'
            
        except Exception:
            return 'unknown'
    
    def _calculate_intersection_confidence(self, feature1: Any, feature2: Any) -> float:
        """Calculate confidence in feature intersection."""
        try:
            confidence = 0.5  # Base confidence
            
            # Factor in individual feature confidences
            if hasattr(feature1, 'confidence') and feature1.confidence is not None:
                confidence *= feature1.confidence
            if hasattr(feature2, 'confidence') and feature2.confidence is not None:
                confidence *= feature2.confidence
                
            return confidence
            
        except Exception:
            return 0.3
    
    def _assess_kinematic_compatibility(self, feature: Any, geological_model: Any) -> Dict[str, float]:
        """Assess kinematic compatibility with other features."""
        try:
            compatibility_scores = {
                'extension_compatibility': 0.0,
                'compression_compatibility': 0.0,
                'strike_slip_compatibility': 0.0,
                'overall_compatibility': 0.0
            }
            
            # Simple compatibility assessment based on orientations
            compatible_features = 0
            total_features = max(len(geological_model.structural_features) - 1, 1)
            
            for other_feature in geological_model.structural_features:
                if other_feature.feature_id != feature.feature_id:
                    if self._orientations_are_compatible(feature, other_feature):
                        compatible_features += 1
            
            compatibility_score = compatible_features / total_features
            compatibility_scores['overall_compatibility'] = compatibility_score
            compatibility_scores['extension_compatibility'] = compatibility_score * 0.8
            compatibility_scores['compression_compatibility'] = compatibility_score * 0.9
            compatibility_scores['strike_slip_compatibility'] = compatibility_score * 0.7
            
            return compatibility_scores
            
        except Exception:
            return {'extension_compatibility': 0.3, 'compression_compatibility': 0.3,
                   'strike_slip_compatibility': 0.3, 'overall_compatibility': 0.3}
    
    def _orientations_are_compatible(self, feature1: Any, feature2: Any) -> bool:
        """Check if feature orientations are kinematically compatible."""
        try:
            # Simple compatibility check based on strike similarity
            if (hasattr(feature1, 'strike') and hasattr(feature2, 'strike') and
                feature1.strike is not None and feature2.strike is not None):
                
                strike_diff = abs(feature1.strike - feature2.strike)
                # Consider compatible if strikes are within 30 degrees
                return strike_diff < 30.0 or strike_diff > 330.0
                
            return True  # Assume compatible if no orientation data
            
        except Exception:
            return True
    
    async def _discover_structural_causality(self, structural_features: List[Dict[str, Any]]) -> np.ndarray:
        """Discover causal relationships between structural features using causal algorithms."""
        try:
            if len(structural_features) < 2:
                return np.zeros((len(structural_features), len(structural_features)))
            
            # Create data matrix from structural features for causal analysis
            feature_data = self._create_structural_feature_matrix(structural_features)
            feature_names = [f["feature_id"] for f in structural_features]
            
            # Apply multiple causal discovery algorithms
            causality_results = {}
            
            # PC Algorithm for constraint-based discovery
            if hasattr(self, 'causal_algorithms') and 'pc_algorithm' in self.causal_algorithms:
                try:
                    pc_result = await self._run_pc_algorithm_on_structural_data(feature_data, feature_names)
                    causality_results['pc_algorithm'] = pc_result
                except Exception as e:
                    self.logger.warning(f"PC algorithm failed on structural data: {e}")
            
            # Correlation-based simple causality discovery as fallback
            correlation_matrix = np.corrcoef(feature_data.T)
            causality_matrix = (np.abs(correlation_matrix) > 0.5).astype(int)
            np.fill_diagonal(causality_matrix, 0)  # Remove self-loops
            
            causality_results['correlation_based'] = causality_matrix
            
            # Ensemble the results
            if len(causality_results) > 1:
                final_matrix = np.mean([result for result in causality_results.values()], axis=0)
                final_matrix = (final_matrix > 0.5).astype(int)
            else:
                final_matrix = list(causality_results.values())[0]
            
            return final_matrix
            
        except Exception as e:
            self.logger.error(f"Error in structural causality discovery: {e}")
            n_features = len(structural_features)
            return np.zeros((n_features, n_features))
    
    def _create_structural_feature_matrix(self, structural_features: List[Dict[str, Any]]) -> np.ndarray:
        """Create data matrix from structural features for causal analysis."""
        try:
            n_features = len(structural_features)
            
            # Extract numerical attributes for causal analysis
            feature_matrix = np.zeros((100, n_features))  # Assume 100 data points
            
            for i, feature in enumerate(structural_features):
                # Create synthetic time series based on feature attributes
                base_values = []
                
                # Use causal potential scores as base values
                causal_potential = feature.get('causal_potential', {})
                base_values.extend([
                    causal_potential.get('structural_control', 0.5),
                    causal_potential.get('fluid_flow_influence', 0.5),
                    causal_potential.get('stress_concentration', 0.5),
                    causal_potential.get('deformation_pathway', 0.5)
                ])
                
                # Use network position metrics
                network_position = feature.get('causal_connectivity', {}).get('network_position', {})
                base_values.extend([
                    network_position.get('degree_centrality', 0.3),
                    network_position.get('betweenness_centrality', 0.3)
                ])
                
                # Create time series with noise
                base_value = np.mean(base_values)
                time_series = base_value + 0.1 * np.random.randn(100)
                feature_matrix[:, i] = time_series
            
            return feature_matrix
            
        except Exception:
            # Return random data as fallback
            return np.random.randn(100, len(structural_features))
    
    async def _run_pc_algorithm_on_structural_data(self, data: np.ndarray, variable_names: List[str]) -> np.ndarray:
        """Run PC algorithm on structural feature data."""
        try:
            # Simple PC algorithm implementation
            n_vars = data.shape[1]
            adjacency_matrix = np.zeros((n_vars, n_vars))
            
            # Calculate partial correlations as conditional independence test
            for i in range(n_vars):
                for j in range(i + 1, n_vars):
                    # Simple correlation test (would be improved with proper CI testing)
                    correlation = np.corrcoef(data[:, i], data[:, j])[0, 1]
                    if abs(correlation) > 0.3:  # Threshold for significance
                        adjacency_matrix[i, j] = 1
                        adjacency_matrix[j, i] = 1
            
            return adjacency_matrix
            
        except Exception:
            # Return empty matrix on failure
            return np.zeros((data.shape[1], data.shape[1]))
    
    def _build_structural_causal_network(self, structural_features: List[Dict[str, Any]], 
                                       causality_matrix: np.ndarray) -> Dict[str, Any]:
        """Build a causal network representation of structural features."""
        try:
            import networkx as nx
            
            # Create directed graph
            G = nx.DiGraph()
            
            # Add nodes (structural features)
            for i, feature in enumerate(structural_features):
                G.add_node(
                    feature['feature_id'], 
                    feature_type=feature['feature_type'],
                    causal_potential=feature.get('causal_potential', {}),
                    spatial_geometry=feature.get('spatial_geometry', {})
                )
            
            # Add edges based on causality matrix
            for i in range(len(structural_features)):
                for j in range(len(structural_features)):
                    if causality_matrix[i, j] > 0:
                        G.add_edge(
                            structural_features[i]['feature_id'],
                            structural_features[j]['feature_id'],
                            weight=float(causality_matrix[i, j]),
                            causal_strength=float(causality_matrix[i, j])
                        )
            
            # Calculate network metrics
            network_metrics = {
                'number_of_nodes': G.number_of_nodes(),
                'number_of_edges': G.number_of_edges(),
                'density': nx.density(G),
                'is_connected': nx.is_weakly_connected(G),
                'number_of_components': nx.number_weakly_connected_components(G)
            }
            
            # Calculate centrality measures
            try:
                centrality_measures = {
                    'in_degree_centrality': nx.in_degree_centrality(G),
                    'out_degree_centrality': nx.out_degree_centrality(G),
                    'betweenness_centrality': nx.betweenness_centrality(G),
                    'closeness_centrality': nx.closeness_centrality(G)
                }
            except:
                centrality_measures = {}
            
            return {
                'network_graph': G,
                'network_metrics': network_metrics,
                'centrality_measures': centrality_measures,
                'adjacency_matrix': causality_matrix.tolist(),
                'node_attributes': {node: G.nodes[node] for node in G.nodes()},
                'edge_attributes': {edge: G.edges[edge] for edge in G.edges()}
            }
            
        except ImportError:
            self.logger.warning("NetworkX not available for network analysis")
            return {
                'adjacency_matrix': causality_matrix.tolist(),
                'network_metrics': {'number_of_nodes': len(structural_features)},
                'error': 'NetworkX not available'
            }
        except Exception as e:
            self.logger.error(f"Error building structural causal network: {e}")
            return {'error': str(e)}
    
    def _rank_structural_feature_importance(self, structural_features: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Rank structural features by their causal importance."""
        try:
            feature_rankings = []
            
            for feature in structural_features:
                # Calculate importance score based on multiple factors
                importance_score = 0.0
                
                # Causal potential contribution
                causal_potential = feature.get('causal_potential', {})
                importance_score += causal_potential.get('structural_control', 0.0) * 0.3
                importance_score += causal_potential.get('fluid_flow_influence', 0.0) * 0.25
                importance_score += causal_potential.get('stress_concentration', 0.0) * 0.25
                importance_score += causal_potential.get('deformation_pathway', 0.0) * 0.2
                
                # Network position contribution
                network_position = feature.get('causal_connectivity', {}).get('network_position', {})
                importance_score += network_position.get('degree_centrality', 0.0) * 0.15
                importance_score += network_position.get('betweenness_centrality', 0.0) * 0.1
                
                # Feature type bonus
                feature_type_bonus = {
                    'fault': 0.1,
                    'fracture': 0.08,
                    'contact': 0.07,
                    'vein': 0.05,
                    'fold': 0.06
                }
                importance_score += feature_type_bonus.get(feature.get('feature_type', '').lower(), 0.0)
                
                feature_rankings.append({
                    'feature_id': feature['feature_id'],
                    'feature_type': feature.get('feature_type', 'unknown'),
                    'importance_score': importance_score,
                    'ranking_factors': {
                        'causal_potential_score': sum(causal_potential.values()) / max(len(causal_potential), 1),
                        'network_centrality_score': sum(network_position.values()) / max(len(network_position), 1),
                        'feature_type_bonus': feature_type_bonus.get(feature.get('feature_type', '').lower(), 0.0)
                    }
                })
            
            # Sort by importance score (descending)
            feature_rankings.sort(key=lambda x: x['importance_score'], reverse=True)
            
            # Add rank numbers
            for i, ranking in enumerate(feature_rankings):
                ranking['rank'] = i + 1
            
            return feature_rankings
            
        except Exception as e:
            self.logger.error(f"Error ranking structural features: {e}")
            return []
    
