    async def _analyze_sample_temporal_causality(self, geological_model: Any) -> Dict[str, Any]:
        """Analyze temporal causality in geological samples."""
        try:
            if not hasattr(geological_model, 'samples') or len(geological_model.samples) == 0:
                return {'temporal_relationships': [], 'time_series_analysis': {}}
            
            # Extract temporal information from samples
            temporal_data = []
            for sample in geological_model.samples:
                if hasattr(sample, 'timestamp') and sample.timestamp is not None:
                    temporal_data.append({
                        'sample_id': sample.sample_id,
                        'timestamp': sample.timestamp,
                        'location': sample.location.tolist(),
                        'quality': getattr(sample, 'quality', 1.0),
                        'lithology': getattr(sample, 'lithology', 'unknown')
                    })
            
            # Sort by timestamp
            temporal_data.sort(key=lambda x: x['timestamp'])
            
            # Analyze temporal sequences
            temporal_relationships = []
            for i in range(len(temporal_data) - 1):
                current_sample = temporal_data[i]
                next_sample = temporal_data[i + 1]
                
                time_diff = (next_sample['timestamp'] - current_sample['timestamp']).total_seconds()
                spatial_distance = np.linalg.norm(
                    np.array(next_sample['location']) - np.array(current_sample['location'])
                )
                
                # Calculate causal potential based on temporal proximity and spatial distance
                temporal_causal_strength = max(0.0, 1.0 - time_diff / (365 * 24 * 3600))  # Normalize by 1 year
                spatial_causal_strength = max(0.0, 1.0 - spatial_distance / 10000.0)  # Normalize by 10km
                
                combined_causal_strength = (temporal_causal_strength + spatial_causal_strength) / 2.0
                
                if combined_causal_strength > 0.3:
                    temporal_relationships.append({
                        'source_sample': current_sample['sample_id'],
                        'target_sample': next_sample['sample_id'],
                        'time_difference_days': time_diff / (24 * 3600),
                        'spatial_distance_m': spatial_distance,
                        'temporal_causal_strength': temporal_causal_strength,
                        'spatial_causal_strength': spatial_causal_strength,
                        'combined_causal_strength': combined_causal_strength
                    })
            
            return {
                'temporal_relationships': temporal_relationships,
                'time_series_analysis': {
                    'total_samples': len(temporal_data),
                    'time_span_days': (temporal_data[-1]['timestamp'] - temporal_data[0]['timestamp']).days if len(temporal_data) > 1 else 0,
                    'sampling_frequency': len(temporal_data) / max((temporal_data[-1]['timestamp'] - temporal_data[0]['timestamp']).days, 1) if len(temporal_data) > 1 else 0
                }
            }
            
        except Exception as e:
            self.logger.error(f"Error in sample temporal causality analysis: {e}")
            return {'error': str(e)}
    
    async def _build_lithological_causal_networks(self, geological_model: Any) -> Dict[str, Any]:
        """Build causal networks based on lithological relationships."""
        try:
            self.logger.info("Building lithological causal networks")
            
            lithology_network = {
                'nodes': [],
                'edges': [],
                'network_properties': {}
            }
            
            # Create nodes from lithology units
            for unit in geological_model.lithology_units:
                node = {
                    'unit_id': unit.unit_id,
                    'rock_type': unit.rock_type,
                    'formation': getattr(unit, 'formation', 'unknown'),
                    'properties': getattr(unit, 'properties', {}),
                    'causal_influence_score': self._calculate_lithology_causal_influence(unit)
                }
                lithology_network['nodes'].append(node)
            
            # Create edges based on contact relationships and property similarities
            for i, unit1 in enumerate(geological_model.lithology_units):
                for j, unit2 in enumerate(geological_model.lithology_units[i+1:], i+1):
                    
                    causal_relationship = self._analyze_lithology_causal_relationship(unit1, unit2)
                    
                    if causal_relationship['causal_strength'] > 0.3:
                        edge = {
                            'source': unit1.unit_id,
                            'target': unit2.unit_id,
                            'causal_strength': causal_relationship['causal_strength'],
                            'relationship_type': causal_relationship['relationship_type'],
                            'mechanism': causal_relationship['mechanism']
                        }
                        lithology_network['edges'].append(edge)
            
            # Calculate network properties
            lithology_network['network_properties'] = {
                'total_nodes': len(lithology_network['nodes']),
                'total_edges': len(lithology_network['edges']),
                'network_density': len(lithology_network['edges']) / max((len(lithology_network['nodes']) * (len(lithology_network['nodes']) - 1)) / 2, 1)
            }
            
            return lithology_network
            
        except Exception as e:
            self.logger.error(f"Error building lithological causal networks: {e}")
            return {'error': str(e)}
    
    def _calculate_lithology_causal_influence(self, unit: Any) -> float:
        """Calculate the causal influence score for a lithological unit."""
        try:
            influence_score = 0.0
            
            # Rock type influence
            rock_type_influences = {
                'igneous': 0.8,  # High influence due to heat and chemical alteration
                'metamorphic': 0.7,  # Moderate to high influence
                'sedimentary': 0.5  # Moderate influence
            }
            influence_score += rock_type_influences.get(unit.rock_type.lower(), 0.5)
            
            # Property-based influences
            if hasattr(unit, 'properties') and unit.properties:
                properties = unit.properties
                
                # Density influence
                density = properties.get('density', 2.7)
                density_influence = min((density - 2.0) / 2.0, 1.0)  # Normalize around typical rock density
                influence_score += 0.2 * density_influence
                
                # Permeability influence (affects fluid flow)
                permeability = properties.get('permeability', 1e-15)
                perm_influence = min(np.log10(permeability + 1e-20) / -10.0, 1.0)  # Log scale normalization
                influence_score += 0.1 * perm_influence
                
                # Elastic modulus influence (affects stress transmission)
                elastic_modulus = properties.get('elastic_modulus', 50e9)
                elastic_influence = min(elastic_modulus / 100e9, 1.0)
                influence_score += 0.1 * elastic_influence
            
            return min(influence_score, 1.0)
            
        except Exception:
            return 0.5
    
    def _analyze_lithology_causal_relationship(self, unit1: Any, unit2: Any) -> Dict[str, Any]:
        """Analyze causal relationship between two lithological units."""
        try:
            relationship = {
                'causal_strength': 0.0,
                'relationship_type': 'unknown',
                'mechanism': 'unknown'
            }
            
            # Analyze based on rock types
            rock_type_1 = unit1.rock_type.lower()
            rock_type_2 = unit2.rock_type.lower()
            
            # Define causal relationships between rock types
            causal_relationships = {
                ('igneous', 'metamorphic'): {'strength': 0.9, 'type': 'transformation', 'mechanism': 'contact_metamorphism'},
                ('igneous', 'sedimentary'): {'strength': 0.7, 'type': 'alteration', 'mechanism': 'thermal_alteration'},
                ('metamorphic', 'sedimentary'): {'strength': 0.6, 'type': 'overprinting', 'mechanism': 'structural_overprinting'},
                ('sedimentary', 'metamorphic'): {'strength': 0.8, 'type': 'transformation', 'mechanism': 'regional_metamorphism'}
            }
            
            # Check both directions
            key1 = (rock_type_1, rock_type_2)
            key2 = (rock_type_2, rock_type_1)
            
            if key1 in causal_relationships:
                rel_data = causal_relationships[key1]
                relationship['causal_strength'] = rel_data['strength']
                relationship['relationship_type'] = rel_data['type']
                relationship['mechanism'] = rel_data['mechanism']
            elif key2 in causal_relationships:
                rel_data = causal_relationships[key2]
                relationship['causal_strength'] = rel_data['strength'] * 0.8  # Slightly reduced for reverse direction
                relationship['relationship_type'] = rel_data['type']
                relationship['mechanism'] = rel_data['mechanism']
            
            # Enhance based on property similarities/differences
            if (hasattr(unit1, 'properties') and hasattr(unit2, 'properties') and 
                unit1.properties and unit2.properties):
                
                property_similarity = self._calculate_property_similarity(unit1.properties, unit2.properties)
                
                # Similar properties suggest potential for interaction
                if property_similarity > 0.7:
                    relationship['causal_strength'] += 0.2
                elif property_similarity < 0.3:
                    relationship['causal_strength'] += 0.1  # Contrasting properties also suggest interaction potential
            
            return relationship
            
        except Exception as e:
            return {
                'causal_strength': 0.0,
                'relationship_type': 'unknown',
                'mechanism': 'unknown',
                'error': str(e)
            }
    
    def _calculate_property_similarity(self, props1: Dict[str, float], props2: Dict[str, float]) -> float:
        """Calculate similarity between two property dictionaries."""
        try:
            common_properties = set(props1.keys()) & set(props2.keys())
            if not common_properties:
                return 0.5  # No common properties, assume moderate similarity
            
            similarities = []
            for prop in common_properties:
                val1 = props1[prop]
                val2 = props2[prop]
                
                # Calculate normalized difference
                max_val = max(abs(val1), abs(val2), 1e-10)
                similarity = 1.0 - abs(val1 - val2) / max_val
                similarities.append(similarity)
            
            return np.mean(similarities)
            
        except Exception:
            return 0.5
    
    async def integrate_geological_statistics(self, geological_data: Any, 
                                            causal_results: Dict[str, Any]) -> Dict[str, Any]:
        """
        Integrate geological statistics with causal discovery methods.
        
        This method incorporates advanced statistical methods for geological data analysis
        including circular statistics, directional analysis, and multi-scale stability
        assessment to enhance causal inference with geological domain expertise.
        """
        try:
            # Import geological statistics components
            from .geological_statistics import (
                CircularStatistics, HypothesisTesting, OrientationAnalysis, 
                StabilityAnalysis, calculate_skewness, calculate_kurtosis
            )
            
            self.logger.info("Integrating geological statistics with causal discovery")
            
            integration_results = {
                'circular_statistical_causality': await self._analyze_circular_statistical_causality(geological_data),
                'directional_causal_relationships': await self._discover_directional_causal_relationships(geological_data),
                'orientation_based_causality': await self._perform_orientation_based_causal_analysis(geological_data),
                'multi_scale_causal_stability': await self._assess_multi_scale_causal_stability(geological_data),
                'statistical_causal_validation': await self._validate_causal_relationships_statistically(causal_results, geological_data),
                'uncertainty_quantified_causality': await self._quantify_causal_uncertainty_statistically(causal_results, geological_data),
                'hypothesis_driven_causal_testing': await self._perform_hypothesis_driven_causal_testing(geological_data),
                'distributional_causal_analysis': await self._analyze_distributional_causal_patterns(geological_data)
            }
            
            # Calculate overall integration confidence
            confidence_scores = []
            for analysis_key, analysis_results in integration_results.items():
                if isinstance(analysis_results, dict) and 'confidence' in analysis_results:
                    confidence_scores.append(analysis_results['confidence'])
                elif isinstance(analysis_results, dict) and 'quality_score' in analysis_results:
                    confidence_scores.append(analysis_results['quality_score'])
            
            overall_confidence = np.mean(confidence_scores) if confidence_scores else 0.5
            
            integration_results['integration_summary'] = {
                'overall_confidence': float(overall_confidence),
                'confidence_level': self._classify_confidence_level(overall_confidence),
                'analyses_performed': len(integration_results),
                'statistical_methods_applied': self._get_statistical_methods_summary()
            }
            
            self.logger.info(f"Geological statistics integration completed with {overall_confidence:.3f} confidence")
            return integration_results
            
        except Exception as e:
            self.logger.error(f"Error in geological statistics integration: {str(e)}")
            return {
                'error': str(e),
                'integration_status': 'failed',
                'fallback_analysis': await self._provide_basic_statistical_fallback()
            }
    
    async def _analyze_circular_statistical_causality(self, geological_data: Any) -> Dict[str, Any]:
        """Analyze causal relationships using circular statistics for orientation data."""
        try:
            circular_stats = CircularStatistics()
            causal_results = {
                'circular_causal_networks': {},
                'orientation_influences': {},
                'statistical_significance': {},
                'circular_correlation_strengths': {}
            }
            
            # Extract orientation data from geological structures
            orientation_data = self._extract_orientation_data(geological_data)
            
            if not orientation_data:
                return {'error': 'No orientation data found', 'confidence': 0.0}
            
            # Analyze directional causality between different structural elements
            for structure_type in orientation_data.keys():
                if len(orientation_data[structure_type]) >= 5:
                    angles_rad = np.array(orientation_data[structure_type]) * np.pi / 180.0
                    
                    # Compute comprehensive circular statistics
                    stats = circular_stats.compute_advanced_circular_statistics(angles_rad)
                    
                    # Fit multiple circular distributions
                    vm_fit = circular_stats.fit_von_mises_distribution(angles_rad)
                    watson_fit = circular_stats.fit_watson_distribution(angles_rad)
                    fisher_fit = circular_stats.fit_fisher_distribution(angles_rad)
                    
                    # Assess causal influence potential based on concentration
                    causal_influence = self._assess_circular_causal_influence(stats, vm_fit)
                    
                    causal_results['circular_causal_networks'][structure_type] = {
                        'circular_statistics': stats,
                        'von_mises_parameters': vm_fit,
                        'watson_parameters': watson_fit,
                        'fisher_parameters': fisher_fit,
                        'causal_influence_score': causal_influence,
                        'directional_coherence': float(stats['mean_resultant_length']),
                        'dispersion_measure': float(stats['circular_variance'])
                    }
            
            # Cross-structure causal analysis
            structure_pairs = [(s1, s2) for s1 in orientation_data.keys() 
                             for s2 in orientation_data.keys() if s1 != s2]
            
            for struct1, struct2 in structure_pairs:
                if (len(orientation_data[struct1]) >= 3 and 
                    len(orientation_data[struct2]) >= 3):
                    
                    correlation_strength = self._calculate_circular_correlation(
                        orientation_data[struct1], orientation_data[struct2]
                    )
                    
                    causal_results['circular_correlation_strengths'][f"{struct1}_to_{struct2}"] = {
                        'correlation_coefficient': correlation_strength,
                        'causal_likelihood': self._estimate_causal_likelihood_from_correlation(correlation_strength),
                        'directional_similarity': self._assess_directional_similarity(
                            orientation_data[struct1], orientation_data[struct2]
                        )
                    }
            
            # Overall confidence assessment
            confidence = self._assess_circular_analysis_confidence(causal_results)
            causal_results['confidence'] = confidence
            causal_results['analysis_quality'] = self._grade_circular_analysis_quality(confidence)
            
            return causal_results
            
        except Exception as e:
            self.logger.error(f"Error in circular statistical causality analysis: {str(e)}")
            return {'error': str(e), 'confidence': 0.0}
    
    async def _discover_directional_causal_relationships(self, geological_data: Any) -> Dict[str, Any]:
        """Discover causal relationships based on directional data analysis."""
        try:
            hypothesis_testing = HypothesisTesting()
            directional_results = {
                'directional_causal_graphs': {},
                'uniformity_tests': {},
                'directional_clustering': {},
                'causal_flow_patterns': {}
            }
            
            # Extract directional measurements
            directional_data = self._extract_directional_measurements(geological_data)
            
            if not directional_data:
                return {'error': 'No directional data found', 'confidence': 0.0}
            
            # Perform comprehensive hypothesis testing for each directional dataset
            for measurement_type, angles in directional_data.items():
                if len(angles) >= 5:
                    angles_rad = np.array(angles) * np.pi / 180.0
                    
                    # Multiple uniformity tests
                    rayleigh_stat, rayleigh_p = hypothesis_testing.rayleigh_test(angles_rad)
                    kuiper_stat, kuiper_p = hypothesis_testing.kuiper_test(angles_rad)
                    watson_stat, watson_p = hypothesis_testing.watson_u2_test(angles_rad)
                    hr_stat, hr_p = hypothesis_testing.hermans_rasson_test(angles_rad)
                    
                    # Test for specific directional preferences
                    directional_tests = {}
                    test_directions = [0, 45, 90, 135]  # Test common geological directions
                    
                    for test_dir in test_directions:
                        test_result = hypothesis_testing.test_specific_mean_direction(
                            angles_rad, np.radians(test_dir)
                        )
                        directional_tests[f'direction_{test_dir}'] = test_result
                    
                    # Assess causal implications of non-uniformity
                    non_uniform_evidence = min(rayleigh_p, kuiper_p, watson_p)
                    causal_directional_strength = 1.0 - non_uniform_evidence if non_uniform_evidence < 0.05 else 0.0
                    
                    directional_results['uniformity_tests'][measurement_type] = {
                        'rayleigh_test': {'statistic': rayleigh_stat, 'p_value': rayleigh_p},
                        'kuiper_test': {'statistic': kuiper_stat, 'p_value': kuiper_p},
                        'watson_test': {'statistic': watson_stat, 'p_value': watson_p},
                        'hermans_rasson_test': {'statistic': hr_stat, 'p_value': hr_p},
                        'directional_preference_tests': directional_tests,
                        'causal_directional_strength': causal_directional_strength,
                        'preferred_direction_evidence': non_uniform_evidence < 0.05
                    }
            
            # Analyze directional clustering patterns
            clustering_results = await self._analyze_directional_clustering_causality(directional_data)
            directional_results['directional_clustering'] = clustering_results
            
            # Identify causal flow patterns
            flow_patterns = await self._identify_causal_flow_patterns(directional_data)
            directional_results['causal_flow_patterns'] = flow_patterns
            
            # Overall confidence assessment
            confidence = self._assess_directional_causal_confidence(directional_results)
            directional_results['confidence'] = confidence
            
            return directional_results
            
        except Exception as e:
            self.logger.error(f"Error in directional causal relationship discovery: {str(e)}")
            return {'error': str(e), 'confidence': 0.0}
    
