    # Helper methods for geological statistics integration
    
    def _extract_orientation_data(self, geological_data: Any) -> Dict[str, List[float]]:
        """Extract orientation data from geological structures."""
        orientation_data = {}
        
        try:
            # If geological_data has structural features
            if hasattr(geological_data, 'structural_features'):
                for feature in geological_data.structural_features:
                    feature_type = getattr(feature, 'feature_type', 'unknown')
                    if feature_type not in orientation_data:
                        orientation_data[feature_type] = []
                    
                    # Extract strike values
                    if hasattr(feature, 'strike') and feature.strike is not None:
                        orientation_data[feature_type].append(float(feature.strike))
                    
            # If geological_data is a dictionary
            elif isinstance(geological_data, dict):
                structural_features = geological_data.get('structural_features', [])
                for feature in structural_features:
                    feature_type = feature.get('feature_type', 'unknown')
                    if feature_type not in orientation_data:
                        orientation_data[feature_type] = []
                    
                    strike = feature.get('strike')
                    if strike is not None:
                        orientation_data[feature_type].append(float(strike))
        
        except Exception as e:
            self.logger.error(f"Error extracting orientation data: {str(e)}")
        
        return orientation_data
    
    def _assess_circular_causal_influence(self, stats: Dict, vm_fit: Dict) -> float:
        """Assess causal influence potential from circular statistics."""
        try:
            # High concentration indicates stronger potential causal influence
            concentration = vm_fit.get('kappa', 0)
            resultant_length = stats.get('mean_resultant_length', 0)
            
            # Combine concentration and resultant length for influence score
            influence_score = (concentration / (concentration + 1)) * resultant_length
            
            return float(min(influence_score, 1.0))
        
        except Exception:
            return 0.5
    
    def _calculate_circular_correlation(self, angles1: List[float], angles2: List[float]) -> float:
        """Calculate circular correlation between two sets of angles."""
        try:
            angles1_rad = np.array(angles1) * np.pi / 180.0
            angles2_rad = np.array(angles2) * np.pi / 180.0
            
            min_length = min(len(angles1_rad), len(angles2_rad))
            angles1_rad = angles1_rad[:min_length]
            angles2_rad = angles2_rad[:min_length]
            
            # Circular correlation using circular moments
            cos1, sin1 = np.cos(angles1_rad), np.sin(angles1_rad)
            cos2, sin2 = np.cos(angles2_rad), np.sin(angles2_rad)
            
            # Circular correlation coefficient
            r_cc = (np.mean(cos1 * cos2) + np.mean(sin1 * sin2))
            r_ss = (np.mean(sin1 * cos2) - np.mean(cos1 * sin2))
            
            circular_corr = np.sqrt(r_cc**2 + r_ss**2)
            
            return float(min(circular_corr, 1.0))
        
        except Exception:
            return 0.0
    
    def _get_statistical_methods_summary(self) -> List[str]:
        """Get summary of statistical methods applied."""
        return [
            'Circular statistics (Von Mises, Watson, Fisher distributions)',
            'Directional hypothesis testing (Rayleigh, Kuiper, Watson U2)',
            'Multi-scale stability analysis',
            'Bootstrap validation and uncertainty quantification',
            'Distributional pattern analysis',
            'Orientation-based causal inference',
            'Cross-validation and permutation testing'
        ]
    
    def _classify_confidence_level(self, confidence: float) -> str:
        """Classify confidence level."""
        if confidence > 0.8:
            return 'high'
        elif confidence > 0.6:
            return 'moderate'
        elif confidence > 0.4:
            return 'low'
        else:
            return 'very_low'
    
