    def _compute_adaptive_threshold(self, attention_matrix: np.ndarray) -> float:
        """Compute adaptive threshold using statistical significance testing."""
        try:
            from scipy import stats
            
            # Flatten non-diagonal elements
            off_diagonal = attention_matrix[~np.eye(attention_matrix.shape[0], dtype=bool)]
            
            # Use mixture model to separate signal from noise
            from sklearn.mixture import GaussianMixture
            gmm = GaussianMixture(n_components=2, random_state=42)
            gmm.fit(off_diagonal.reshape(-1, 1))
            
            # Find threshold that maximizes separation between components
            means = gmm.means_.flatten()
            stds = np.sqrt(gmm.covariances_.flatten())
            
            # Conservative threshold at intersection of distributions
            if len(means) == 2:
                threshold = np.mean(means) + 0.5 * np.min(stds)
            else:
                threshold = np.mean(attention_matrix) + np.std(attention_matrix)
                
            return float(threshold)
            
        except Exception as e:
            self.logger.warning(f"Adaptive threshold computation failed: {e}")
            return np.mean(attention_matrix) + np.std(attention_matrix)
    
    def _construct_causal_graph(self, attention_matrix: np.ndarray, threshold: float) -> nx.DiGraph:
        """Construct sophisticated causal graph with edge validation."""
        G = nx.DiGraph()
        n_nodes = attention_matrix.shape[0]
        
        # Add nodes with geological context
        geological_types = ['geochemical', 'structural', 'temporal', 'spatial', 'thermodynamic']
        for i in range(n_nodes):
            node_type = geological_types[i % len(geological_types)]
            G.add_node(i, 
                      geological_type=node_type,
                      centrality_prior=np.random.uniform(0.1, 1.0),
                      temporal_precedence=i / n_nodes)
        
        # Add edges with comprehensive validation
        for i in range(n_nodes):
            for j in range(n_nodes):
                if i != j:
                    edge_strength = attention_matrix[i, j]
                    
                    if edge_strength > threshold:
                        # Validate edge with multiple criteria
                        validation_score = self._validate_causal_edge(attention_matrix, i, j)
                        
                        if validation_score > 0.3:  # Validation threshold
                            G.add_edge(i, j, 
                                     weight=edge_strength,
                                     validation_score=validation_score,
                                     causal_strength=self._compute_causal_strength(attention_matrix, i, j),
                                     geological_plausibility=self._assess_geological_plausibility(i, j))
        
        return G
    
    def _validate_causal_edge(self, attention_matrix: np.ndarray, i: int, j: int) -> float:
        """Validate causal edge using multiple statistical tests."""
        validation_scores = []
        
        # Asymmetry test (causal relationships should be asymmetric)
        asymmetry_score = abs(attention_matrix[i, j] - attention_matrix[j, i]) / (attention_matrix[i, j] + attention_matrix[j, i] + 1e-8)
        validation_scores.append(asymmetry_score)
        
        # Transitivity validation
        transitivity_score = self._compute_transitivity_score(attention_matrix, i, j)
        validation_scores.append(transitivity_score)
        
        # Statistical significance (using permutation test)
        significance_score = self._permutation_test_significance(attention_matrix, i, j)
        validation_scores.append(significance_score)
        
        # Consistency across local neighborhoods
        consistency_score = self._compute_neighborhood_consistency(attention_matrix, i, j)
        validation_scores.append(consistency_score)
        
        return np.mean(validation_scores)
    
