    async def _check_causal_data_drift(self, data: np.ndarray, algorithm: str) -> Dict[str, Any]:
        """Check for data drift in causal discovery context"""
        try:
            if not hasattr(self, 'drift_detectors') or not self.drift_detectors:
                return {'drift_detected': False, 'message': 'No drift detection configured'}
            
            drift_results = {}
            overall_drift = False
            
            # Check drift for each feature
            for i in range(min(data.shape[1], len(self.drift_detectors))):
                feature_name = f"feature_{i}"
                
                if feature_name in self.drift_detectors:
                    detector_config = self.drift_detectors[feature_name]
                    detector = detector_config['detector']
                    config = detector_config['config']
                    
                    # Current data for this feature
                    current_data = data[:, i]
                    current_data = current_data[~np.isnan(current_data)]
                    
                    if len(current_data) > 10:
                        drift_report = detector.detect_drift(
                            feature_name, current_data, 
                            method=config['method'], 
                            threshold=config['threshold']
                        )
                        
                        drift_results[feature_name] = {
                            'drift_detected': drift_report.drift_detected,
                            'drift_score': drift_report.drift_score,
                            'p_value': drift_report.p_value,
                            'method': drift_report.statistical_test
                        }
                        
                        if drift_report.drift_detected:
                            overall_drift = True
            
            return {
                'overall_drift_detected': overall_drift,
                'feature_drift_results': drift_results,
                'algorithm': algorithm
            }
            
        except Exception as e:
            self.logger.warning(f"Failed to check causal data drift: {e}")
            return {'drift_detected': False, 'error': str(e)}
    
    async def _log_drift_detection_results(self, experiment_id: str, drift_report: Dict[str, Any]):
        """Log drift detection results to MLOps pipeline"""
        try:
            if hasattr(self, 'mlops_pipeline') and self.mlops_pipeline:
                drift_metrics = {
                    'overall_drift_detected': int(drift_report.get('overall_drift_detected', False)),
                    'drift_feature_count': len(drift_report.get('feature_drift_results', {})),
                    'algorithm': drift_report.get('algorithm', 'unknown')
                }
                
                # Add individual feature drift scores
                for feature, results in drift_report.get('feature_drift_results', {}).items():
                    drift_metrics[f"drift_score_{feature}"] = results.get('drift_score', 0.0)
                    drift_metrics[f"drift_pvalue_{feature}"] = results.get('p_value', 1.0)
                
                await self.mlops_pipeline.log_metrics(experiment_id, drift_metrics)
                self.logger.debug(f"Logged drift detection results for experiment {experiment_id}")
            
        except Exception as e:
            self.logger.warning(f"Failed to log drift detection results: {e}")
    
