    async def _check_temporal_causal_consistency(self, adjacency_matrix: np.ndarray, variable_names: List[str]) -> float:
        """Check temporal consistency of causal relationships"""
        try:
            # This would check if causal directions respect temporal ordering
            # For geological processes, some relationships have known temporal precedence
            
            temporal_scores = []
            n_vars = len(variable_names)
            
            # Known temporal relationships in geological processes
            temporal_precedence = {
                'magma_intrusion': ['deformation', 'seismic_activity', 'gas_emission'],
                'tectonic_stress': ['fault_activation', 'seismic_activity'],
                'precipitation': ['groundwater_level', 'landslide_risk'],
                'volcanic_inflation': ['seismic_swarms', 'gas_emissions']
            }
            
            for cause_idx in range(n_vars):
                for effect_idx in range(n_vars):
                    if adjacency_matrix[cause_idx, effect_idx] > 0:
                        cause_name = variable_names[cause_idx]
                        effect_name = variable_names[effect_idx]
                        
                        # Check temporal consistency
                        temporal_score = self._check_temporal_relationship(cause_name, effect_name, temporal_precedence)
                        temporal_scores.append(temporal_score)
            
            return np.mean(temporal_scores) if temporal_scores else 0.8
            
        except Exception as e:
            self.logger.warning(f"Failed to check temporal consistency: {e}")
            return 0.8
    
    def _check_temporal_relationship(self, cause: str, effect: str, temporal_precedence: Dict[str, List[str]]) -> float:
        """Check if a causal relationship respects known temporal precedence"""
        try:
            # Check if cause typically precedes effect in geological processes
            for precedent, consequences in temporal_precedence.items():
                if precedent.lower() in cause.lower():
                    if any(cons.lower() in effect.lower() for cons in consequences):
                        return 1.0  # Strong temporal consistency
                elif precedent.lower() in effect.lower():
                    if any(cons.lower() in cause.lower() for cons in consequences):
                        return 0.2  # Likely reversed causation
            
            # If no specific temporal relationship is known, assume moderate consistency
            return 0.6
            
        except Exception:
            return 0.6
    
